import{_ as r,o as e,c as o,a2 as a}from"./chunks/framework.C9_66ieh.js";const b=JSON.parse('{"title":"Keyboard shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"keyboard-shortcuts.md","filePath":"keyboard-shortcuts.md","lastUpdated":1785284531000}'),n={name:"keyboard-shortcuts.md"};function s(d,t,l,i,h,g){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p>TrueDeck claims these shortcuts <strong>before</strong> xterm and agent CLIs, so they work while a terminal tab is focused. Hold <strong>Ctrl</strong> on Windows/Linux or <strong>⌘</strong> on macOS (<code>metaKey</code> is treated like Ctrl).</p><p>Normal terminal keys (including <strong>Ctrl+C</strong>) still reach the PTY unless listed below.</p><h2 id="application" tabindex="-1">Application <a class="header-anchor" href="#application" aria-label="Permalink to &quot;Application&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><strong>Ctrl+O</strong></td><td>Open / add project folder</td></tr><tr><td><strong>Ctrl+T</strong></td><td>New agent (open agent palette)</td></tr><tr><td><strong>Ctrl+N</strong></td><td>New shell tab</td></tr><tr><td><strong>Ctrl+W</strong></td><td>Close active tab</td></tr><tr><td><strong>Ctrl+S</strong></td><td>Toggle settings</td></tr><tr><td><strong>Escape</strong></td><td>Close settings and agent palette</td></tr></tbody></table><p><strong>Ctrl+S</strong> and <strong>Ctrl+T</strong> still work when focus is in settings form fields (other shortcuts are ignored while typing outside the terminal).</p><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><strong>Ctrl+Tab</strong></td><td>Next tab in the <strong>focused pane group</strong> only</td></tr><tr><td><strong>Ctrl+Shift+Tab</strong></td><td>Previous tab in the focused pane group</td></tr><tr><td><strong>Ctrl+1</strong> … <strong>Ctrl+9</strong></td><td>Jump to tab 1-9</td></tr></tbody></table><h2 id="pane-splits" tabindex="-1">Pane splits <a class="header-anchor" href="#pane-splits" aria-label="Permalink to &quot;Pane splits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><strong>Ctrl+D</strong></td><td>Split vertical (side-by-side)</td></tr><tr><td><strong>Ctrl+X</strong></td><td>Split horizontal (top / bottom)</td></tr><tr><td><strong>Ctrl+Alt+D</strong> or <strong>Ctrl+Alt+X</strong></td><td>Merge all groups into one pane</td></tr><tr><td><strong>Ctrl+←</strong> / <strong>Ctrl+→</strong> / <strong>Ctrl+↑</strong> / <strong>Ctrl+↓</strong></td><td>Move focus to neighboring pane (spatial). With one pane, cycles tabs.</td></tr></tbody></table><p>Notes:</p><ul><li>You need <strong>2+ tabs</strong> (or an existing multi-pane layout) to split.</li><li>Max <strong>16</strong> panes.</li><li>Split moves the <strong>active</strong> tab into a new leaf relative to the focused group.</li></ul><h2 id="terminal-font-zoom" tabindex="-1">Terminal font zoom <a class="header-anchor" href="#terminal-font-zoom" aria-label="Permalink to &quot;Terminal font zoom&quot;">​</a></h2><p>These change <strong>terminal font size</strong> (saved in settings), not Chromium page zoom.</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><strong>Ctrl+=</strong> or <strong>Ctrl++</strong></td><td>Larger font (11-20px)</td></tr><tr><td><strong>Ctrl+-</strong></td><td>Smaller font</td></tr><tr><td><strong>Ctrl+0</strong></td><td>Reset to 13px</td></tr></tbody></table><h2 id="agent-tui-scroll-grok-etc" tabindex="-1">Agent TUI scroll (Grok, etc.) <a class="header-anchor" href="#agent-tui-scroll-grok-etc" aria-label="Permalink to &quot;Agent TUI scroll (Grok, etc.)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Input</th><th>Action</th></tr></thead><tbody><tr><td><strong>Mouse wheel</strong></td><td>Sent to the agent’s custom TUI scroll (mouse reporting)</td></tr><tr><td><strong>Shift+wheel</strong></td><td>Host xterm scrollback (when available)</td></tr></tbody></table><p>Native scrollbars are suppressed while the agent owns the wheel so reporting is not stolen.</p><h2 id="terminal-not-claimed" tabindex="-1">Terminal (not claimed) <a class="header-anchor" href="#terminal-not-claimed" aria-label="Permalink to &quot;Terminal (not claimed)&quot;">​</a></h2><p>TrueDeck intentionally leaves many combos to the shell / agent TUI, for example:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Typical meaning</th></tr></thead><tbody><tr><td><strong>Ctrl+C</strong></td><td>Interrupt / copy (agent-dependent)</td></tr><tr><td><strong>Ctrl+A</strong></td><td>Start of line / agent TUI select-all - <strong>not</strong> the agent palette</td></tr><tr><td><strong>Ctrl+L</strong></td><td>Clear / redraw (agent-dependent)</td></tr></tbody></table><h2 id="settings-cheatsheet" tabindex="-1">Settings cheatsheet <a class="header-anchor" href="#settings-cheatsheet" aria-label="Permalink to &quot;Settings cheatsheet&quot;">​</a></h2><p>Settings → Terminal shows a short hint:</p><blockquote><p><strong>T</strong> new agent · <strong>O</strong> project · <strong>W</strong> close · <strong>S</strong> settings · <strong>D</strong> v-split · <strong>X</strong> h-split · <strong>N</strong> shell · <strong>1-9</strong> jump tab · <strong>+/-</strong> font zoom</p></blockquote><h2 id="source-of-truth" tabindex="-1">Source of truth <a class="header-anchor" href="#source-of-truth" aria-label="Permalink to &quot;Source of truth&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>File</th></tr></thead><tbody><tr><td>Global handlers</td><td><code>src/App.tsx</code></td></tr><tr><td>xterm attach filter + wheel</td><td><code>src/components/TerminalPane.tsx</code></td></tr><tr><td>UI titles</td><td><code>TabBar</code>, chrome, Settings, title-bar buttons</td></tr></tbody></table>',26)])])}const p=r(n,[["render",s]]);export{b as __pageData,p as default};
